import { join } from "node:path";
import { renderCollection, renderIndex, SITE_CSS, type CollectionState } from "../../instagram-archive-core/src/index.ts";
import type { ProgressReporter } from "../../lib/progress.ts";
import type { ArchiveFs } from "./fs.ts";
import { collectionDir, listCollections, readPosts, readState, SAVED_SUFFIX } from "./store.ts";

const ARCHIVE_README = [
  "# Instagram archive",
  "",
  "Generated by `pnpm tools ig`. Each `@name` folder is one collection:",
  "`@username` holds that profile's posts; `@username-saved` holds its Saved tab.",
  "",
  "Each collection contains `records.jsonl` (posts in capture order), `state.json`",
  "(cursor and completion checkpoint), `images/` (downloaded media), and the",
  "rendered `username.html` and `data/` files after `pnpm tools ig build`.",
  "",
  "`index.html` at this root links every collection. Refresh with",
  "`pnpm tools ig update @username ...`, then run `pnpm tools ig build` again.",
  "Sign in to Instagram once in Helium on 127.0.0.1:9222; no cookies are stored here.",
].join("\n") + "\n";

export interface BuildSummary {
  readonly collections: number;
  readonly posts: number;
  readonly indexPath: string;
}

export function buildSite(fs: ArchiveFs, outRoot: string, reporter: ProgressReporter): BuildSummary {
  const states: CollectionState[] = [];
  let posts = 0;
  for (const key of listCollections(fs, outRoot)) {
    const dir = collectionDir(outRoot, key);
    const state = readState(fs, dir, key.endsWith(SAVED_SUFFIX) ? "saved" : "profile", key);
    const collectionPosts = readPosts(fs, dir);
    const page = renderCollection({ state, posts: collectionPosts });
    for (const [name, content] of Object.entries(page.files)) {
      fs.writeText(join(dir, name), content);
    }
    fs.writeText(join(dir, "site.css"), SITE_CSS);
    states.push(state);
    posts += page.count;
    reporter.update({ phase: "build", done: states.length, total: states.length, note: key });
  }
  const indexPath = join(outRoot, "index.html");
  fs.writeText(indexPath, renderIndex(states));
  fs.writeText(join(outRoot, "site.css"), SITE_CSS);
  fs.writeText(join(outRoot, "README.md"), ARCHIVE_README);
  reporter.finish("built " + states.length + " collections, " + posts + " posts");
  return { collections: states.length, posts, indexPath };
}
